const PI = Math.PI, TAU = PI*2, HP = PI/2;
const lerp = (a, b, t) => a + (b - a)*t, clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const sstep = (a, b, x) => { const t = clamp((x - a)/(b - a), 0, 1); return t*t*(3 - 2*t); };
// rings come as flat decimetre ints [x0, z0, x1, z1, ...] in local metres (+x east, +z south)
const dec = a => { const P = []; for (let i = 0; i < a.length; i += 2) P.push([a[i]/10, a[i + 1]/10]); return P; };
const areaS = P => { let s = 0; for (let i = 0, n = P.length; i < n; i++){ const a = P[i], b = P[(i + 1) % n]; s += a[0]*b[1] - b[0]*a[1]; } return s/2; };
const cenP = P => { let A = 0, cx = 0, cz = 0; for (let i = 0, n = P.length; i < n; i++){ const a = P[i], b = P[(i + 1) % n], f = a[0]*b[1] - b[0]*a[1]; A += f; cx += (a[0] + b[0])*f; cz += (a[1] + b[1])*f; } return Math.abs(A) < 1e-9 ? P[0] : [cx/(3*A), cz/(3*A)]; };
const pipP = (P, x, z) => { let c = false; for (let i = 0, j = P.length - 1; i < P.length; j = i++){ const a = P[i], b = P[j]; if ((a[1] > z) !== (b[1] > z) && x < (b[0] - a[0])*(z - a[1])/(b[1] - a[1]) + a[0]) c = !c; } return c; };
const segD = (x, z, a, b) => { const dx = b[0] - a[0], dz = b[1] - a[1], L = dx*dx + dz*dz || 1, t = clamp(((x - a[0])*dx + (z - a[1])*dz)/L, 0, 1); return Math.hypot(x - a[0] - dx*t, z - a[1] - dz*t); };
const edgeD = (P, x, z) => { let d = 1e9; for (let i = 0, n = P.length; i < n; i++) d = Math.min(d, segD(x, z, P[i], P[(i + 1) % n])); return d; };
