    // roof: paving and garden patches (Civic Square and the residents' gardens), 10 m cells
    const hsh = (x, z) => { const s = Math.sin(Math.floor(x/22)*12.9898 + Math.floor(z/22)*78.233)*43758.5453; return s - Math.floor(s); };
    drape((x, z) => hsh(x, z) < 0.42 ? GRN : PAVE, E, () => 20, 10);
    // roof structures mapped as parts of Elements / the station (base >= 10 m, small outlines), not the ICC's skirts
    for (const o of ['w1415166820', 'w1415166825']){ const b = IDX.get(o); for (const [b0, t1, r] of b.p || []){ const P = dec(r);
      if (P.length > 40 || t1 <= 20.5 || b0 > 40) continue; const c = cenP(P); if (Math.hypot(c[0] - ICC_C[0], c[1] - ICC_C[1]) < 48) continue;
      prism(t1 - b0 > 3 ? GLS : SLAB, SLAB, P, Math.max(20, b0), t1); } }
    // the station pavilion (mapped as a cluster of parts 20-36 m): glass boxes with white ribs
    { const b = IDX.get('w1047822829'); for (const [b0, t1, r] of b.p){ const P = dec(r); if (P.length > 40) continue; prism(GLS, RIB, P, Math.max(20, b0), t1); } }
    // small service blocks, Sorrento's podium club, the civic block
